(function(){
'use strict';
const data=window.STAGE_GUIDES,M=window.GuideModel,$=id=>document.getElementById(id);
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const venueState={query:'',city:'all',district:'all'},companyState={query:'',focus:'all'};
const outside=(url,label,css='')=>`<a class="${css}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span><span class="sr-only">（另開分頁）</span></a>`;
function sources(item){return `<details class="guide-sources"><summary>核對來源 <span>${esc(item.checkedAt||data.checkedAt)}</span></summary><ul>${item.sources.map(s=>`<li>${outside(s.url,s.label)}</li>`).join('')}</ul></details>`;}
function venueCard(v,index){return `<article class="guide-card venue-card ${v.benchmark?'is-benchmark':''}" id="venue-${esc(v.id)}"><div class="guide-card-top"><span class="guide-index">${String(index+1).padStart(2,'0')}</span><span class="guide-location">${esc(v.city)} · ${esc(v.district)}${v.benchmark?' · 參考起點':''}</span></div><h3>${esc(v.name)}</h3>${v.hallName?`<p class="hall-name">${esc(v.hallName)}</p>`:''}<div class="guide-tags">${v.format?`<span>${esc(v.format)}</span>`:''}</div>${v.capacityText?`<p class="venue-capacity"><span>空間與席位</span>${esc(v.capacityText)}</p>`:''}<p class="guide-description">${esc(v.summary)}</p>${v.note?`<p class="guide-card-note">${esc(v.note)}</p>`:''}<div class="venue-address"><span aria-hidden="true">⌖</span><p><span>場館地址</span>${esc(v.address)}</p></div><div class="guide-card-actions">${outside(v.mapsUrl,'Google Maps','map-link')}${outside(v.officialUrl,'場館官網','guide-official')}</div>${sources(v)}</article>`;}
function companyCard(c,index){return `<article class="guide-card company-card ${c.benchmark?'is-benchmark':''}" id="company-${esc(c.id)}"><div class="guide-card-top"><span class="guide-index">${String(index+1).padStart(2,'0')}</span><span class="guide-location">${esc(c.entityType)}${c.benchmark?' · 參考起點':''}</span></div><h3>${esc(c.name)}</h3>${c.city?`<p class="company-city">${esc(c.city)} · 官方聯絡所在地</p>`:''}<div class="guide-tags">${c.focusTags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="guide-description">${esc(c.summary)}</p><div class="guide-card-actions">${outside(c.officialUrl,c.officialLabel||'認識這個團隊','guide-official')}</div>${sources(c)}</article>`;}
function noResults(label){return `<div class="guide-empty"><span aria-hidden="true">◌</span><h3>還沒有符合條件的${label}</h3><p>試試其他關鍵字，或按上方「清除篩選」查看全部選集。</p></div>`;}
function renderVenues(){renderVenueDistricts();const list=M.venues(data.venues,venueState);$('venue-count').textContent=`${list.length} / ${data.venues.length} 處空間`;$('venue-list').innerHTML=list.length?list.map(v=>venueCard(v,data.venues.indexOf(v))).join(''):noResults('劇場');}
function renderCompanies(){const list=M.companies(data.companies,companyState);$('company-count').textContent=`${list.length} / ${data.companies.length} 組團隊`;$('company-list').innerHTML=list.length?list.map(c=>companyCard(c,data.companies.indexOf(c))).join(''):noResults('團隊');}
function renderVenueDistricts(){$('venue-district').innerHTML='<option value="all">所有行政區</option>'+[...new Set(data.venues.filter(v=>venueState.city==='all'||v.city===venueState.city).map(v=>v.district))].sort((a,b)=>a.localeCompare(b,'zh-Hant')).map(d=>`<option>${esc(d)}</option>`).join('');$('venue-district').value=venueState.district;}
$('venue-city').innerHTML='<option value="all">雙北全部</option>'+[...new Set(data.venues.map(v=>v.city))].map(c=>`<option>${esc(c)}</option>`).join('');
$('company-focus').innerHTML='<option value="all">所有方向</option>'+[...new Set(data.companies.flatMap(c=>c.focusTags))].sort((a,b)=>a.localeCompare(b,'zh-Hant')).map(t=>`<option>${esc(t)}</option>`).join('');
$('venue-city').addEventListener('change',e=>{venueState.city=e.target.value;venueState.district='all';renderVenues()});
$('venue-search').addEventListener('input',e=>{venueState.query=e.target.value;renderVenues()});$('venue-district').addEventListener('change',e=>{venueState.district=e.target.value;renderVenues()});$('venue-reset').addEventListener('click',()=>{venueState.query='';venueState.city='all';venueState.district='all';$('venue-city').value='all';$('venue-search').value='';$('venue-district').value='all';renderVenues()});
$('company-search').addEventListener('input',e=>{companyState.query=e.target.value;renderCompanies()});$('company-focus').addEventListener('change',e=>{companyState.focus=e.target.value;renderCompanies()});$('company-reset').addEventListener('click',()=>{companyState.query='';companyState.focus='all';$('company-search').value='';$('company-focus').value='all';renderCompanies()});
renderVenues();renderCompanies();
})();
